// The reference pack's manifest (generated by scripts/build-reference-pack.mts and
// committed). Used by the server (cover endpoint) and, through a dynamic import, by the
// browser; it never enters the first-load JS of any route.
import { z } from "zod";
import raw from "./pack-manifest.json";

export const packManifestSchema = z.object({
  version: z.string().min(1).max(40),
  model: z.literal("clip-vit-base-patch32"),
  dim: z.literal(512),
  /** File name under /reference-pack/: it embeds a hash of its bytes, so it cannot drift. */
  vectors: z.string().regex(/^vectors-[0-9a-f]{8}\.bin$/),
  games: z.array(
    z.object({
      bggId: z.string().regex(/^\d{1,9}$/),
      name: z.string().min(1).max(200),
      year: z.number().int().nullable(),
      rank: z.number().int().min(1),
      coverUrl: z
        .string()
        .max(500)
        .regex(/^https:\/\//),
    }),
  ),
});
export type PackManifest = z.infer<typeof packManifestSchema>;

let parsed: PackManifest | undefined;
let byId: Map<string, string> | undefined;
let infoById: Map<string, PackGameInfo> | undefined;

export type PackGameInfo = { bggId: string; name: string; rank: number };

export function getPackManifest(): PackManifest {
  parsed ??= packManifestSchema.parse(raw);
  return parsed;
}

/** Name and BGG rank of a pack game id (`bgg:<bggId>`); null for anything else. */
export function packGameInfo(gameId: string): PackGameInfo | null {
  if (!gameId.startsWith("bgg:")) return null;
  infoById ??= new Map(
    getPackManifest().games.map((g) => [
      g.bggId,
      { bggId: g.bggId, name: g.name, rank: g.rank },
    ]),
  );
  return infoById.get(gameId.slice(4)) ?? null;
}

/** The cover URL listed for a BGG id; null for anything else (a Map, so no prototype keys). */
export function packCoverUrl(bggId: string): string | null {
  byId ??= new Map(getPackManifest().games.map((g) => [g.bggId, g.coverUrl]));
  return byId.get(bggId) ?? null;
}
